SELECT cc.cc_call_center_id, cc.cc_name, d_cl.d_date AS closed_date, COUNT(sr.sr_ticket_number) AS total_returns, COALESCE(SUM(sr.sr_return_amt), 0) AS total_return_amount, CASE WHEN COALESCE(SUM(sr.sr_return_amt), 0) > 10000 THEN 'High' WHEN COALESCE(SUM(sr.sr_return_amt), 0) BETWEEN 5000 AND 10000 THEN 'Medium' ELSE 'Low' END AS return_volume_category, AVG(t.t_hour) AS avg_return_hour, RANK() OVER (ORDER BY COALESCE(SUM(sr.sr_return_amt), 0) DESC) AS return_amount_rank FROM call_center cc JOIN date_dim d_cl ON cc.cc_closed_date_sk = d_cl.d_date_sk LEFT JOIN store_returns sr ON sr.sr_returned_date_sk = d_cl.d_date_sk LEFT JOIN time_dim t ON sr.sr_return_time_sk = t.t_time_sk GROUP BY cc.cc_call_center_id, cc.cc_name, d_cl.d_date
